import React, { useState } from 'react';
import { Card, Input, Button, List, Typography, Spin, Space } from 'antd';
import { SendOutlined, DownloadOutlined, BarChartOutlined } from '@ant-design/icons';
import axios from 'axios';

const { Text } = Typography;

const Chat = ({ onShowDashboard }) => {
  const [input, setInput] = useState('');
  const [messages, setMessages] = useState([
    { type: 'bot', text: 'O que você quer monitorar?\n\nPode me dizer temas, assuntos ou empresas que gostaria de extrair um relatório de comunicação.' }
  ]);
  const [loading, setLoading] = useState(false);
  const [noticias, setNoticias] = useState([]);
  const [temaAtual, setTemaAtual] = useState('');
  const [aguardandoPeriodo, setAguardandoPeriodo] = useState(false);
  const [aguardandoAcao, setAguardandoAcao] = useState(false);

  const handleSend = async (customInput) => {
    const userInput = typeof customInput === 'string' ? customInput : input;
    if (!userInput.trim()) return;
    setMessages(prev => [...prev, { type: 'user', text: userInput }]);
    setLoading(true);
    setAguardandoPeriodo(false);
    setAguardandoAcao(false);
    try {
      const res = await axios.post('http://localhost:4000/api/noticias', { termo: userInput });
      const noticiasResp = res.data;
      setNoticias(noticiasResp);
      setTemaAtual(userInput);
      if (noticiasResp.length === 0) {
        setMessages(prev => [
          ...prev,
          { type: 'bot', text: 'Não encontrei notícias recentes sobre esse tema. Se quiser, tente outro assunto ou pergunte de outra forma! 😊' }
        ]);
      } else {
        setMessages(prev => [
          ...prev,
          { type: 'bot', text: `Encontrei ${noticiasResp.length} notícias sobre esse tema! Deseja ver notícias de algum período específico? (ex: últimos 7 dias, mês passado, etc)` }
        ]);
        setAguardandoPeriodo(true);
      }
    } catch (e) {
      setMessages(prev => [
        ...prev,
        { type: 'bot', text: 'Tive um probleminha ao buscar as notícias agora. Que tal tentar novamente em alguns instantes ou perguntar sobre outro tema? 😉' }
      ]);
    }
    setLoading(false);
    setInput('');
  };

  const handlePeriodo = (periodo) => {
    // Simula filtro por período (mock)
    setMessages(prev => [
      ...prev,
      { type: 'user', text: periodo },
      { type: 'bot', text: `Aqui estão as notícias do período: ${periodo}.` },
      ...noticias.slice(0, 5).map(n => ({ type: 'news', noticia: n }))
    ]);
    if (noticias.length > 1) {
      setMessages(prev => [
        ...prev,
        { type: 'bot', text: 'Deseja baixar essas notícias em uma planilha ou gerar um dashboard com dados sobre elas?' }
      ]);
      setAguardandoAcao(true);
    }
    setAguardandoPeriodo(false);
  };

  const handleAcao = async (acao) => {
    setMessages(prev => [
      ...prev,
      { type: 'user', text: acao },
      { type: 'bot', text: acao === 'planilha' ? 'Gerando planilha para download...' : 'Gerando dashboard com indicadores das notícias...' }
    ]);
    setAguardandoAcao(false);
    if (acao === 'dashboard' && onShowDashboard) {
      // Buscar dados do dashboard no backend
      setLoading(true);
      try {
        const res = await axios.post('http://localhost:4000/api/dashboard', { termo: temaAtual });
        onShowDashboard(res.data);
      } catch (e) {
        setMessages(prev => [
          ...prev,
          { type: 'bot', text: 'Erro ao gerar o dashboard.' }
        ]);
      }
      setLoading(false);
    }
    // Aqui pode acionar lógica real de download ou dashboard
  };

  return (
    <div style={{ width: '100%', maxWidth: 420, margin: '0 auto', height: '100%', display: 'flex', flexDirection: 'column' }}>
      <div style={{ background: '#fff', borderRadius: 12, boxShadow: '0 2px 12px #e6e6e6', flex: 1, minHeight: 400, display: 'flex', flexDirection: 'column', position: 'relative', height: '100%' }}>
        <div style={{ flex: 1, overflowY: 'auto', padding: 24 }}>
          <List
            dataSource={messages}
            renderItem={msg =>
              msg.type === 'news' ? (
                <List.Item style={{ background: '#f6f6ff', margin: '8px 0', borderRadius: 8, border: '1px solid #ececff' }}>
                  <div>
                    <Text strong>{msg.noticia.titulo}</Text>
                    <div><Text type="secondary">{msg.noticia.fonte} - {new Date(msg.noticia.data).toLocaleDateString()}</Text></div>
                    <div>{msg.noticia.descricao}</div>
                  </div>
                </List.Item>
              ) : (
                <List.Item style={{ justifyContent: msg.type === 'user' ? 'flex-end' : 'flex-start', background: msg.type === 'user' ? '#e6f7ff' : 'transparent', borderRadius: 8, margin: '8px 0', border: msg.type === 'user' ? '1px solid #bae7ff' : 'none' }}>
                  <Text>{msg.text}</Text>
                </List.Item>
              )
            }
          />
          {loading && <Spin style={{ margin: '10px 0' }} />}
          {aguardandoPeriodo && (
            <Space style={{ margin: '10px 0' }}>
              <Button onClick={() => handlePeriodo('últimos 7 dias')}>Últimos 7 dias</Button>
              <Button onClick={() => handlePeriodo('mês passado')}>Mês passado</Button>
              <Button onClick={() => handlePeriodo('todo o período')}>Todo o período</Button>
            </Space>
          )}
          {aguardandoAcao && (
            <Space style={{ margin: '10px 0' }}>
              <Button icon={<DownloadOutlined />} onClick={() => handleAcao('planilha')}>Baixar planilha</Button>
              <Button icon={<BarChartOutlined />} onClick={() => handleAcao('dashboard')}>Gerar dashboard</Button>
            </Space>
          )}
        </div>
        <Card style={{ background: '#f3eaff', borderRadius: '0 0 12px 12px', boxShadow: '0 -2px 8px #e6e6e6', margin: 0, position: 'sticky', bottom: 0, zIndex: 2 }} bodyStyle={{ padding: 12 }}>
          <Input.Group compact>
            <Input
              style={{ width: '85%' }}
              placeholder="Digite um tema, empresa ou assunto..."
              value={input}
              onChange={e => setInput(e.target.value)}
              onPressEnter={() => handleSend()}
              disabled={loading}
            />
            <Button type="primary" icon={<SendOutlined />} onClick={() => handleSend()} disabled={loading} />
          </Input.Group>
        </Card>
      </div>
    </div>
  );
};

export default Chat;
